initial_condition:
with {
    the SUT being in the "initial state" and
    and containing a list of entities
}

test_cases.then:
then {
    the SUT sends a valid Response for the operations:
        Batch Update Entities with Response Status Code set to 204     and
        Query Entities with Updated Entities set to '${updated_entities}' valid entities
}

test_cases.when:
when {
    the SUT receives a Request from the client containing:
        URL set to '/ngsi-ld/v1/entityOperations/update?${params_as_string}'
        method set to 'POST'
        Request batch update operation over entity from filename '@{entities_to_be_updated}' with overwrite_option set to '${EMPTY}' and Content-Type set to 'application/ld+json'
}
